// TestTrailStatusColor_ColorsActiveStatuses verifies the trail-specific mapping:
// open/merged/closed are colored; draft (in-progress) and unknown stay default.
func TestTrailStatusColor_ColorsActiveStatuses(t *testing.T) {
	t.Parallel()
	styles := newStatusStyles(&bytes.Buffer{}) // mapping is independent of color-enabled
	cases := map[trail.Status]bool{
		trail.StatusOpen:    true,
		trail.StatusMerged:  true,
		trail.StatusClosed:  true,
		trail.StatusDraft:   false,
		trail.Status("???"): false,
	}
	for status, wantOK := range cases {
		if _, ok := trailStatusColor(styles, status); ok != wantOK {
			t.Errorf("trailStatusColor(%q) ok = %v, want %v", status, ok, wantOK)
		}
	}
}

// TestPrintTrailListPlainWhenNotATerminal guards the regression that list output
// to a non-terminal writer stays plain (no ANSI escapes) and unchanged.
func TestPrintTrailListPlainWhenNotATerminal(t *testing.T) {
	t.Parallel()
	var out bytes.Buffer
	printTrailList(&out, []*trail.Metadata{
		{Branch: "feat/a", Status: trail.StatusMerged, UpdatedAt: time.Now()},
		{Branch: "fix/b", Status: trail.StatusClosed, UpdatedAt: time.Now()},
	}, trailListDisplayOptions{StatusFilters: nil, TotalMatched: 2})

	text := out.String()
	if strings.Contains(text, "\x1b[") {
		t.Errorf("non-terminal list output should have no ANSI escapes, got:\n%q", text)
	}
	for _, want := range []string{"merged", "closed"} {
		if !strings.Contains(text, want) {
			t.Errorf("output missing %q, got:\n%s", want, text)
		}
	}
}

